const _byCode = new Map(ASSET_CLASSES.map((c) => [c.code, c]));

export function getAssetClass(code: string): AssetClass | undefined {
  return _byCode.get(code);
}

// Type-to-search over description or code. Empty query returns a capped list.
export function searchAssetClasses(query: string, limit = 60): AssetClass[] {
  const q = query.trim().toLowerCase();
  if (!q) return ASSET_CLASSES.slice(0, limit);
  const starts: AssetClass[] = [];
  const contains: AssetClass[] = [];
  for (const c of ASSET_CLASSES) {
    const d = c.description.toLowerCase();
    const code = c.code.toLowerCase();
    if (d.startsWith(q) || code.startsWith(q)) starts.push(c);
    else if (d.includes(q) || code.includes(q)) contains.push(c);
    if (starts.length >= limit) break;
  }
  return [...starts, ...contains].slice(0, limit);
}
